func UpdatedAtLT(v time.Time) predicate.QAArchiveShard {
	return predicate.QAArchiveShard(sql.FieldLT(FieldUpdatedAt, v))
}

// UpdatedAtLTE applies the LTE predicate on the "updated_at" field.
func UpdatedAtLTE(v time.Time) predicate.QAArchiveShard {
	return predicate.QAArchiveShard(sql.FieldLTE(FieldUpdatedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.QAArchiveShard) predicate.QAArchiveShard {
	return predicate.QAArchiveShard(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.QAArchiveShard) predicate.QAArchiveShard {
	return predicate.QAArchiveShard(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.QAArchiveShard) predicate.QAArchiveShard {
	return predicate.QAArchiveShard(sql.NotPredicates(p))
}
